   755	 * @brief Get a SSH String out of the buffer and adjusts the read pointer.
   756	 *
   757	 * @param[in]  buffer   The buffer to read.
   758	 *
   759	 * @returns             The SSH String, NULL on error.
   760	 */
   761	struct ssh_string_struct *
   762	ssh_buffer_get_ssh_string(struct ssh_buffer_struct *buffer)
   763	{
   764	    uint32_t stringlen;
   765	    uint32_t hostlen;
   766	    struct ssh_string_struct *str = NULL;
   767	    int rc;
   768	
   769	    rc = ssh_buffer_get_u32(buffer, &stringlen);
   770	    if (rc == 0) {
   771	        return NULL;
   772	    }
   773	    hostlen = ntohl(stringlen);
   774	    /* verify if there is enough space in buffer to get it */
   775	    rc = ssh_buffer_validate_length(buffer, hostlen);
   776	    if (rc != SSH_OK) {
   777	      return NULL; /* it is indeed */
   778	    }
   779	    str = ssh_string_new(hostlen);
   780	    if (str == NULL) {
   781	        return NULL;
   782	    }
   783	
   784	    stringlen = ssh_buffer_get_data(buffer, ssh_string_data(str), hostlen);
   785	    if (stringlen != hostlen) {
   786	        /* should never happen */
   787	        SAFE_FREE(str);
   788	        return NULL;
   789	    }
   790	
   791	    return str;
   792	}
